"""Synthetic legal playback fixtures, never generated by an AI model. PyAV 19."""
from pathlib import Path
from fractions import Fraction
import av
import numpy as np
import wave
import struct,zlib

root=Path(__file__).resolve().parent
def chunk(tag,data):return struct.pack('>I',len(data))+tag+data+struct.pack('>I',zlib.crc32(tag+data))
(root/'sample.png').write_bytes(b'\x89PNG\r\n\x1a\n'+chunk(b'IHDR',struct.pack('>IIBBBBB',160,96,8,2,0,0,0))+
    chunk(b'IDAT',zlib.compress((b'\0'+bytes([80,120,160])*160)*96))+chunk(b'IEND',b''))
with av.open(str(root/'sample.webm'),'w',format='webm') as container:
    stream=container.add_stream('libvpx-vp9',rate=8)
    stream.width,stream.height,stream.pix_fmt=160,96,'yuv420p'
    for index in range(8):
        image=np.zeros((96,160,3),dtype=np.uint8)
        image[:,:,index%3]=100+index*10
        frame=av.VideoFrame.from_ndarray(image,format='rgb24')
        for packet in stream.encode(frame):container.mux(packet)
    for packet in stream.encode():container.mux(packet)
with av.open(str(root/'sample.flac'),'w',format='flac') as container:
    stream=container.add_stream('flac',rate=44100)
    stream.layout='mono'
    signal=(np.sin(np.arange(44100)*2*np.pi*440/44100)*3000).astype(np.int16)[None,:]
    frame=av.AudioFrame.from_ndarray(signal,format='s16',layout='mono')
    frame.sample_rate=44100
    for packet in stream.encode(frame):container.mux(packet)
    for packet in stream.encode():container.mux(packet)
print('Created synthetic VP9 WebM and mono FLAC, one second each; no model inference.')
